begin;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,name text not null,department text not null default '',role text not null default 'employee' check(role in ('employee','admin','ombudsman','super_admin')),active boolean not null default false,created_at timestamptz default now());
create function public.br_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,name,department) values(new.id,left(coalesce(new.raw_user_meta_data->>'name','Colaborador'),120),left(coalesce(new.raw_user_meta_data->>'department',''),120));return new;end $$;
create trigger br_new_user after insert on auth.users for each row execute function public.br_new_user();
create function public.br_role() returns text language sql stable security definer set search_path='' as $$ select role from public.profiles where id=auth.uid() and active $$;
create function public.br_staff() returns boolean language sql stable security definer set search_path='' as $$ select coalesce(public.br_role() in ('admin','super_admin'),false) $$;
create table public.posts(id uuid primary key default gen_random_uuid(),kind text not null check(kind in ('news','notice','transport','courses','handbook','birthdays','events','polls','recognition','lost','directory','jobs')),title text not null check(length(title) between 1 and 200),body text not null default '',extra jsonb not null default '{}',published boolean not null default false,author uuid not null default auth.uid() references public.profiles(id),created_at timestamptz default now());
create table public.requests(id uuid primary key default gen_random_uuid(),kind text not null check(kind in ('sac','suggestions','ombudsman','lost')),title text not null,body text not null,owner uuid not null default auth.uid() references public.profiles(id),status text not null default 'Recebido' check(status in ('Recebido','Em análise','Respondido','Encerrado')),response text not null default '',created_at timestamptz default now());
create table public.votes(post_id uuid references public.posts(id) on delete cascade,user_id uuid default auth.uid() references public.profiles(id) on delete cascade,choice text not null,primary key(post_id,user_id));
create table public.progress(post_id uuid references public.posts(id) on delete cascade,user_id uuid default auth.uid() references public.profiles(id) on delete cascade,completed boolean default true,primary key(post_id,user_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,post_id uuid references public.posts(id) on delete cascade,title text not null,read boolean default false,created_at timestamptz default now(),unique(user_id,post_id));
create table public.devices(endpoint text primary key,user_id uuid not null default auth.uid() references public.profiles(id) on delete cascade,subscription jsonb not null,created_at timestamptz default now());
create table public.push_queue(id bigint generated always as identity primary key,notification_id uuid references public.notifications(id) on delete cascade,endpoint text references public.devices(endpoint) on delete cascade,status text not null default 'pending',attempts integer not null default 0,next_at timestamptz default now(),error text,unique(notification_id,endpoint));
create function public.br_notice() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.kind in ('notice','news') and new.published and (tg_op='INSERT' or old.published is distinct from new.published) then insert into public.notifications(user_id,post_id,title) select id,new.id,new.title from public.profiles where active and id<>new.author on conflict do nothing; insert into public.push_queue(notification_id,endpoint) select n.id,d.endpoint from public.notifications n join public.devices d on d.user_id=n.user_id where n.post_id=new.id on conflict do nothing; end if;return new;end $$;
create trigger br_notice after insert or update of published on public.posts for each row execute function public.br_notice();
create function public.br_claim() returns table(job_id bigint,endpoint text,subscription jsonb,title text,notification_id uuid,attempts integer) language sql security definer set search_path='' as $$ with picked as (select q.id from public.push_queue q join public.notifications n on n.id=q.notification_id join public.profiles p on p.id=n.user_id and p.active join public.posts s on s.id=n.post_id and s.published and (s.kind<>'notice' or coalesce(s.extra->>'expires','9999-12-31') >= to_char(now() at time zone 'America/Bahia','YYYY-MM-DD')) join public.devices d on d.endpoint=q.endpoint and d.user_id=n.user_id where q.status in ('pending','sending') and q.next_at<=now() and q.attempts<5 and n.created_at>now()-interval '24 hours' order by q.id limit 30 for update of q skip locked),claimed as(update public.push_queue q set status='sending',attempts=q.attempts+1,next_at=now()+interval '5 minutes' from picked where q.id=picked.id returning q.*) select c.id,c.endpoint,d.subscription,n.title,n.id,c.attempts from claimed c join public.devices d on d.endpoint=c.endpoint join public.notifications n on n.id=c.notification_id $$;
revoke all on function public.br_claim() from public,anon,authenticated;grant execute on function public.br_claim() to service_role;
create function public.br_register_device(p_subscription jsonb) returns void language plpgsql security definer set search_path='' as $$ declare e text:=p_subscription->>'endpoint'; begin if public.br_role() is null or e is null or length(e)>2048 or p_subscription->'keys'->>'p256dh' is null or p_subscription->'keys'->>'auth' is null then raise exception 'Inscrição inválida';end if; delete from public.push_queue where endpoint=e and exists(select 1 from public.devices where endpoint=e and user_id<>auth.uid());insert into public.devices(endpoint,user_id,subscription) values(e,auth.uid(),p_subscription) on conflict(endpoint) do update set user_id=auth.uid(),subscription=excluded.subscription;end $$;
revoke all on function public.br_register_device(jsonb) from public,anon;grant execute on function public.br_register_device(jsonb) to authenticated;
create function public.br_vote(p_post uuid,p_choice text) returns void language plpgsql security definer set search_path='' as $$ begin if public.br_role() is null or not exists(select 1 from public.posts where id=p_post and kind='polls' and published and extra->'choices' ? p_choice) then raise exception 'Opção inválida';end if;insert into public.votes(post_id,user_id,choice) values(p_post,auth.uid(),p_choice);end $$;
revoke all on function public.br_vote(uuid,text) from public,anon;grant execute on function public.br_vote(uuid,text) to authenticated;
create function public.br_poll_results(p_post uuid) returns table(choice text,total bigint) language sql stable security definer set search_path='' as $$ select v.choice,count(*) from public.votes v where v.post_id=p_post and public.br_staff() group by v.choice $$;
revoke all on function public.br_poll_results(uuid) from public,anon;grant execute on function public.br_poll_results(uuid) to authenticated;
alter table public.profiles enable row level security;alter table public.posts enable row level security;alter table public.requests enable row level security;alter table public.votes enable row level security;alter table public.progress enable row level security;alter table public.notifications enable row level security;alter table public.devices enable row level security;alter table public.push_queue enable row level security;
revoke all on public.profiles,public.posts,public.requests,public.votes,public.progress,public.notifications,public.devices,public.push_queue from anon,authenticated;
grant select on public.profiles,public.posts,public.requests,public.votes,public.progress,public.notifications,public.devices to authenticated;grant update(role,active,department) on public.profiles to authenticated;grant insert,delete on public.posts to authenticated;grant update(kind,title,body,extra,published) on public.posts to authenticated;grant insert(kind,title,body) on public.requests to authenticated;grant update(status,response) on public.requests to authenticated;grant insert,update on public.progress to authenticated;grant update(read) on public.notifications to authenticated;grant delete on public.devices to authenticated;
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or public.br_staff());
create policy profile_manage on public.profiles for update to authenticated using(public.br_role()='super_admin' and id<>auth.uid()) with check(public.br_role()='super_admin' and id<>auth.uid());
create policy posts_read on public.posts for select to authenticated using(public.br_role() is not null and (published or public.br_staff()));
create policy posts_insert on public.posts for insert to authenticated with check(public.br_staff() and author=auth.uid());
create policy posts_edit on public.posts for update to authenticated using(public.br_staff()) with check(public.br_staff());
create policy posts_delete on public.posts for delete to authenticated using(public.br_staff());
create policy requests_read on public.requests for select to authenticated using(public.br_role() is not null and (owner=auth.uid() or (kind='ombudsman' and public.br_role()='ombudsman') or (kind<>'ombudsman' and public.br_staff())));
create policy requests_create on public.requests for insert to authenticated with check(public.br_role() is not null and owner=auth.uid() and status='Recebido');
create policy requests_reply on public.requests for update to authenticated using((kind='ombudsman' and public.br_role()='ombudsman') or (kind<>'ombudsman' and public.br_staff())) with check((kind='ombudsman' and public.br_role()='ombudsman') or (kind<>'ombudsman' and public.br_staff()));
create policy votes_read on public.votes for select to authenticated using(public.br_role() is not null and user_id=auth.uid());
create policy progress_read on public.progress for select to authenticated using(public.br_role() is not null and user_id=auth.uid());
create policy progress_insert on public.progress for insert to authenticated with check(public.br_role() is not null and user_id=auth.uid() and exists(select 1 from public.posts where id=post_id and kind='courses' and published));
create policy progress_update on public.progress for update to authenticated using(user_id=auth.uid() and public.br_role() is not null) with check(user_id=auth.uid() and public.br_role() is not null);
create policy notification_read on public.notifications for select to authenticated using(user_id=auth.uid() and public.br_role() is not null);
create policy notification_update on public.notifications for update to authenticated using(user_id=auth.uid() and public.br_role() is not null);
create policy device_read on public.devices for select to authenticated using(user_id=auth.uid() and public.br_role() is not null);
create policy device_delete on public.devices for delete to authenticated using(user_id=auth.uid());
grant select on public.profiles to service_role;
grant select,update on public.push_queue to service_role;
grant select,delete on public.devices to service_role;
alter publication supabase_realtime add table public.notifications;
commit;
